/bin/bash -lc "python - <<'PY'
import json
j=json.load(open('codex_output/bwa_mem_schema.json'))

def walk(inp, path=''):
 name=inp.get('name')
 p=(path+'|'+name) if path and name else (name or path)
 typ=inp.get('type')
 if typ in ('conditional','section'):
  print(p, typ, 'test=', inp.get('test_param',{}).get('name'), 'values=', [c.get('value') for c in inp.get('cases',[])])
  if typ=='conditional':
   for c in inp.get('cases',[]):
    print(' CASE', p, '=', c.get('value'))
    for child in c.get('inputs',[]): walk(child, p)
  else:
   for child in inp.get('inputs',[]): walk(child, p)
 else:
  print(p, typ, 'label=', inp.get('label'), 'value=', inp.get('value'), 'optional=', inp.get('optional'), 'options=', [(o[0], o[1], o[2]) for o in inp.get('options',[])[:10]])
for inp in j['inputs']:
 walk(inp)
print('outputs', json.dumps(j.get('outputs'), indent=2)[:2000])
PY"

