 p=(path+'|'+name) if path and name else (name or path)
 typ=inp.get('type')
 if typ == 'conditional':
  print(p, typ, 'test=', inp.get('test_param',{}).get('name'), 'values=', [c.get('value') for c in inp.get('cases',[])])
  for c in inp.get('cases',[]):
   print(' CASE', p, '=', c.get('value'))
   for child in c.get('inputs',[]): walk(child, p)
 elif typ == 'section':
  print(p, typ)
  for child in inp.get('inputs',[]): walk(child, p)
 else:
  print(p, typ, 'label=', inp.get('label'), 'value=', inp.get('value'), 'optional=', inp.get('optional'), 'options=', opt_summary(inp.get('options',[])))
for inp in j['inputs']:
 walk(inp)
print('outputs')
for o in j.get('outputs',[]): print(o)
